'use client';

import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDownLeft, ArrowLeftRight, ArrowUpRight, Banknote, Check, ChevronLeft, ChevronRight, CircleAlert, ClipboardCheck, Download, Eye, FileText, History, Landmark, LockKeyhole, Pencil, Plus, Search, Wallet, X } from 'lucide-react';
import type { AdminAction, Order, StoreState } from '@/lib/domain';
import { cashAccountKinds, cashBalance, cashDate, cashKindLabels, cashMoney, type CashAccount, type CashAction, type CashCategory, type CashMovement, type CashObligation, type CashPayment, type CashSession, type CashState } from '@/lib/cash-domain';
import './cash-panel.css';
import IonicDialog from '@/components/ionic-dialog';
import { exportCsv } from '@/lib/export-csv';

type PanelProps = { state: StoreState; busy: boolean; onAction: (action: AdminAction, success: string) => Promise<boolean>; error?: string };
type Section = 'overview' | 'movements' | 'sessions' | 'obligations' | 'reconciliation' | 'settings' | 'audit';
type Dialog = { key: string } & (
  | { kind: 'entry'; direction: 'income' | 'expense' }
  | { kind: 'transfer' }
  | { kind: 'open'; account: CashAccount }
  | { kind: 'close'; session: CashSession }
  | { kind: 'account'; account?: CashAccount }
  | { kind: 'category'; category?: CashCategory }
  | { kind: 'obligation' }
  | { kind: 'settle'; obligation: CashObligation }
  | { kind: 'cancel'; obligation: CashObligation }
  | { kind: 'reverse'; movement: CashMovement }
  | { kind: 'refund'; order: Order; remaining: number }
  | { kind: 'reconcile' }
  | { kind: 'detail'; movement: CashMovement }
);
type DialogInput = Dialog extends infer D ? D extends { key: string } ? Omit<D, 'key'> : never : never;
const uid = () => crypto.randomUUID();
const sumLines = (m: CashMovement, account = '') => m.lines.filter(l => !account || l.accountId === account).reduce((sum, l) => sum + l.amountCents, 0);
const localTime = (value: string) => new Intl.DateTimeFormat('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', dateStyle: 'short', timeStyle: 'short' }).format(new Date(value));
const civilLabel = (value: string) => new Intl.DateTimeFormat('es-AR', {dateStyle:'medium',timeZone:'UTC'}).format(new Date(`${value}T12:00:00Z`));
const moneyInput = (cents: number) => (cents / 100).toFixed(2);
const openSession = (cash: CashState, id: string) => cash.sessions.find(s => s.accountId === id && s.status === 'open');
const canUse = (cash: CashState, account: CashAccount) => account.active && (account.kind !== 'cash' || !!openSession(cash, account.id));
const denominations = [20000, 10000, 2000, 1000, 500, 200, 100, 50, 20, 10, 5, 2, 1].map(n => n * 100);
function parseCents(value: string, allowZero = false, negative = false) {
  const text = value.trim();
  if (!(negative ? /^-?\d+(?:[.,]\d{1,2})?$/ : /^\d+(?:[.,]\d{1,2})?$/).test(text)) throw new Error('Ingresá el importe en pesos, sin separador de miles y con hasta dos decimales.');
  const [whole, fraction = ''] = text.replace(',', '.').replace('-', '').split('.');
  const amount = (Number(whole) * 100 + Number(fraction.padEnd(2, '0'))) * (text.startsWith('-') ? -1 : 1);
  if (!Number.isSafeInteger(amount) || Math.abs(amount) > 100_000_000_000 || (!allowZero && amount === 0)) throw new Error('Revisá el importe: debe ser mayor a cero y estar dentro del límite permitido.');
  return amount;
}
function csvDownload(filename:string,rows:(string|number)[][]) {void exportCsv(filename,rows);}
function Modal({title,subtitle,children,onClose,busy=false,wide=false}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void;busy?:boolean;wide?:boolean}) {
  return <IonicDialog label={title} onClose={onClose} busy={busy} wide={wide} className={`adm-modal cash-dialog ${wide?'adm-modal-wide':''}`}><div className="adm-modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button type="button" className="adm-icon" aria-label="Cerrar ventana" disabled={busy} onClick={onClose}><X size={20}/></button></div>{children}</IonicDialog>;
}
function Empty({text}:{text:string}) {return <div className="cash-empty"><Wallet size={30}/><p>{text}</p></div>;}
function AccountIcon({kind}:{kind:CashAccount['kind']}) {return kind==='cash'?<Banknote size={21}/>:kind==='bank'?<Landmark size={21}/>:<Wallet size={21}/>;}
function AccountOptions({cash,exclude = '',all = false}:{cash:CashState;exclude?:string;all?:boolean}) {return <>{cash.accounts.filter(a=>a.active&&a.id!==exclude).map(a=><option key={a.id} value={a.id} disabled={!all&&!canUse(cash,a)}>{a.name}{a.kind==='cash'&&!openSession(cash,a.id)&&!all?' · Abrir turno primero':''}</option>)}</>;}
function ErrorMessage({message}:{message:string}) {return message?<p className="cash-form-error" role="alert"><CircleAlert size={16}/>{message}</p>:null;}
function Summary({label,amount,hint,accent=false}:{label:string;amount:number;hint:string;accent?:boolean}) {return <article className={`cash-stat ${accent?'cash-stat-accent':''}`}><span>{label}</span><strong>{cashMoney(amount)}</strong><small>{hint}</small></article>;}

export default function CashPanel({state,busy,onAction,error:serverError}:PanelProps) {
  const cash=state.cash;
  const today=cashDate(new Date());
  const [section,setSection]=useState<Section>('overview');
  const [from,setFrom]=useState(`${today.slice(0,7)}-01`),[to,setTo]=useState(today);
  const [account,setAccount]=useState(''),[kind,setKind]=useState(''),[category,setCategory]=useState(''),[query,setQuery]=useState('');
  const [page,setPage]=useState(0),[obligationFilter,setObligationFilter]=useState('pending');
  const [dialog,setDialog]=useState<Dialog|null>(null);
  const open=(input:DialogInput)=>setDialog({...input,key:uid()} as Dialog);
  useEffect(()=>setPage(0),[from,to,account,kind,category,query,section,obligationFilter]);
  const movements=useMemo(()=>cash?[...cash.movements].sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)||b.number-a.number):[],[cash]);
  const period=movements.filter(m=>(!from||cashDate(m.occurredAt)>=from)&&(!to||cashDate(m.occurredAt)<=to));
  const filtered=period.filter(m=>(!account||m.lines.some(l=>l.accountId===account))&&(!kind||m.kind===kind)&&(!category||m.categoryId===category)&&`${m.number} ${m.description} ${m.counterparty} ${m.reference} ${m.notes} ${m.categoryName||''} ${m.orderNumber||''}`.toLocaleLowerCase('es').includes(query.trim().toLocaleLowerCase('es')));
  if(!cash)return <section className="adm-panel"><Empty text="Estamos preparando el libro de caja. Actualizá la información del local para comenzar."/></section>;
  const income=period.filter(m=>m.flow==='income').reduce((s,m)=>s+sumLines(m),0);
  const expense=-period.filter(m=>m.flow==='expense').reduce((s,m)=>s+sumLines(m),0);
  const sales=period.filter(m=>m.kind==='sale').reduce((s,m)=>s+sumLines(m),0);
  const refunds=-period.filter(m=>m.kind==='refund'||m.kind==='reversal'&&cash.movements.find(original=>original.id===m.reversalOf)?.kind==='refund').reduce((s,m)=>s+sumLines(m),0);
  const pending=cash.obligations.filter(o=>o.status==='pending');
  const payables=pending.filter(o=>o.direction==='payable').reduce((s,o)=>s+o.totalCents-o.paidCents,0);
  const receivables=pending.filter(o=>o.direction==='receivable').reduce((s,o)=>s+o.totalCents-o.paidCents,0);
  const overdue=pending.filter(o=>o.dueDate<today);
  const pendingRefunds=state.orders.filter(o=>o.paid&&o.status==='cancelado').map(order=>({order,remaining:cash.movements.filter(m=>m.orderId===order.id).reduce((sum,m)=>sum+sumLines(m),0)})).filter(item=>item.remaining>0);
  const activeSessions=cash.sessions.filter(s=>s.status==='open');
  const categoriesExpense=Object.values(period.filter(m=>m.flow==='expense').reduce<Record<string,{name:string;amount:number}>>((acc,m)=>{const id=m.categoryId||'otros';acc[id]??={name:m.categoryName||'Otros egresos',amount:0};acc[id].amount-=sumLines(m);return acc;},{})).sort((a,b)=>b.amount-a.amount);
  const days=Object.entries(period.filter(m=>m.flow!=='internal').reduce<Record<string,{income:number;expense:number}>>((acc,m)=>{const key=cashDate(m.occurredAt);acc[key]??={income:0,expense:0};if(m.flow==='income')acc[key].income+=sumLines(m);else acc[key].expense-=sumLines(m);return acc;},{})).sort(([a],[b])=>a.localeCompare(b)).slice(-14);
  const chartMaximum=Math.max(1,...days.flatMap(([,value])=>[Math.abs(value.income),Math.abs(value.expense)]));
  const pages=Math.max(1,Math.ceil(filtered.length/25)),currentPage=Math.min(page,pages-1);
  const exportMovements=()=>csvDownload(`caja-${from||'inicio'}-${to||today}.csv`,[
    ['Número','Fecha efectiva Argentina','Fecha registro Argentina','Tipo','Concepto','Cuenta','Ingreso ARS','Egreso ARS','Categoría','Contraparte','Comprobante','Pedido','Turno','Reverso de','Conciliado','Responsable','Notas'],
    ...[...filtered].reverse().flatMap(m=>m.lines.filter(l=>!account||l.accountId===account).map(l=>[m.number,localTime(m.occurredAt),localTime(m.createdAt),cashKindLabels[m.kind],m.description,l.accountName,Math.max(0,l.amountCents)/100,Math.max(0,-l.amountCents)/100,m.categoryName||'',m.counterparty,m.reference,m.orderNumber||'',l.sessionId?`#${cash.sessions.find(s=>s.id===l.sessionId)?.number||l.sessionId}`:'',m.reversalOf||'',cash.reconciliations.some(r=>r.accountId===l.accountId&&r.movementIds.includes(m.id))?'Sí':'No',m.actor,m.notes]))
  ]);
  const accountCards=<div className="cash-accounts">{cash.accounts.filter(a=>a.active||cashBalance(cash,a.id)!==0).map(a=><article key={a.id} className="cash-account"><span className={`cash-account-icon cash-account-${a.kind}`}><AccountIcon kind={a.kind}/></span><div><strong>{a.name}</strong><small>{cashAccountKinds[a.kind]}{!a.active?' · Archivada':''}</small></div><b>{cashMoney(cashBalance(cash,a.id))}</b>{a.kind==='cash'&&a.active&&<span className={`cash-pill ${openSession(cash,a.id)?'cash-pill-green':''}`}>{openSession(cash,a.id)?`Turno #${openSession(cash,a.id)!.number} abierto`:'Sin turno abierto'}</span>}</article>)}</div>;
  const movementTable=(items:CashMovement[])=>items.length?<div className="cash-table-region"><p className="cash-scroll-hint"><ArrowLeftRight size={14}/>Deslizá la tabla para ver todas las columnas.</p><div className="cash-table-scroll" role="region" aria-label="Movimientos de caja, tabla con desplazamiento horizontal" tabIndex={0}><table className="cash-table"><thead><tr><th>Movimiento</th><th>Cuenta / concepto</th><th>Entrada</th><th>Salida</th><th>Detalle</th></tr></thead><tbody>{items.map(m=>{const value=sumLines(m,section==='movements'?account:''),isTransfer=m.kind==='transfer';return <tr key={m.id}><td><strong>#{m.number} · {cashKindLabels[m.kind]}</strong><small>{localTime(m.occurredAt)}</small>{m.historical&&<span className="cash-pill">Histórico importado</span>}</td><td><strong>{m.description}</strong><small>{m.lines.filter(l=>section!=='movements'||!account||l.accountId===account).map(l=>l.accountName).join(' → ')}{m.categoryName?` · ${m.categoryName}`:''}</small>{m.counterparty&&<small>{m.counterparty}</small>}</td><td className="cash-positive">{value>0?cashMoney(value):isTransfer&&(section!=='movements'||!account)?cashMoney(m.lines.filter(l=>l.amountCents>0).reduce((s,l)=>s+l.amountCents,0)):'—'}</td><td className="cash-negative">{value<0?cashMoney(-value):isTransfer&&(section!=='movements'||!account)?cashMoney(-m.lines.filter(l=>l.amountCents<0).reduce((s,l)=>s+l.amountCents,0)):'—'}</td><td><button className="adm-icon" aria-label={`Ver detalle de movimiento ${m.number}`} onClick={()=>open({kind:'detail',movement:m})}><Eye size={17}/></button></td></tr>;})}</tbody></table></div></div>:<Empty text="No hay movimientos para estos filtros."/>;
  return <section className="cash-module">
    <div className="cash-heading"><div><span className="adm-eyebrow">CADA PESO, EN SU LUGAR</span><h2>Control de caja</h2><p>Ingresos, egresos y saldos con una historia que siempre podés consultar.</p></div><div className="cash-actions"><button className="adm-btn adm-btn-light" disabled={busy} onClick={()=>open({kind:'transfer'})}><ArrowLeftRight size={16}/>Transferir</button><button className="adm-btn adm-btn-light" disabled={busy} onClick={()=>open({kind:'entry',direction:'expense'})}><ArrowUpRight size={16}/>Egreso</button><button className="adm-btn adm-btn-yellow" disabled={busy} onClick={()=>open({kind:'entry',direction:'income'})}><Plus size={16}/>Ingreso</button></div></div>
    <div className="cash-navigation"><nav className="cash-nav" aria-label="Secciones de caja">{([{id:'overview',label:'Vista general',icon:Wallet},{id:'movements',label:'Movimientos',icon:ArrowLeftRight},{id:'sessions',label:'Turnos y arqueos',icon:Banknote},{id:'obligations',label:'A pagar y cobrar',icon:FileText},{id:'reconciliation',label:'Conciliación',icon:ClipboardCheck},{id:'settings',label:'Cuentas y categorías',icon:Landmark},{id:'audit',label:'Auditoría',icon:History}] as const).map(t=><button key={t.id} className={section===t.id?'cash-nav-active':''} onClick={()=>setSection(t.id)} aria-current={section===t.id?'page':undefined}><t.icon size={16}/>{t.label}{t.id==='obligations'&&overdue.length>0&&<b>{overdue.length}</b>}</button>)}</nav><p className="cash-scroll-hint"><ArrowLeftRight size={14}/>Deslizá para ver todas las secciones de caja.</p></div>
    {(section==='overview'||section==='movements')&&<div className="cash-period"><label>Desde<input type="date" aria-label="Caja desde" value={from} max={to||today} onChange={e=>setFrom(e.target.value)}/></label><label>Hasta<input type="date" aria-label="Caja hasta" value={to} min={from} max={today} onChange={e=>setTo(e.target.value)}/></label><button className="adm-text-btn" onClick={()=>{setFrom(today);setTo(today);}}>Hoy</button><button className="adm-text-btn" onClick={()=>{setFrom(`${today.slice(0,7)}-01`);setTo(today);}}>Este mes</button><small>Fechas del comercio · Argentina</small></div>}
    {section==='overview'&&<>
      <div className="cash-stats"><Summary label="Ingresos netos del período" amount={income} hint={`Ventas ${cashMoney(sales)} · devoluciones ${cashMoney(refunds)}`} accent/><Summary label="Egresos netos del período" amount={expense} hint="Incluye reversos de egresos"/><Summary label="Flujo neto del período" amount={income-expense} hint="Ingresos menos egresos; no es ganancia contable"/><Summary label="Disponible en todas las cuentas" amount={cashBalance(cash)} hint="Saldo actual, incluye fondos iniciales y arqueos"/></div>
      {pendingRefunds.length>0&&<div className="cash-alert"><CircleAlert size={20}/><div><strong>{pendingRefunds.length} devolución{pendingRefunds.length>1?'es':''} pendiente{pendingRefunds.length>1?'s':''} de registrar</strong><p>Cancelar un pedido no mueve dinero. Registrá cada reintegro cuando efectivamente se realice.</p></div><button className="adm-btn adm-btn-light" onClick={()=>setSection('movements')}>Revisar</button></div>}
      {accountCards}
      <div className="cash-grid-two"><section className="adm-panel"><div className="adm-panel-head"><div><h3>El movimiento de tu negocio</h3><p>Últimos 14 días con actividad del período.</p></div><div className="cash-legend"><span>Ingresos</span><span>Egresos</span></div></div>{days.length?<div className="cash-chart" aria-label="Ingresos y egresos por día">{days.map(([date,value])=><div className="cash-chart-day" key={date}><div className="cash-chart-columns"><span className={value.income<0?'cash-chart-negative':''} title={`Ingresos netos ${cashMoney(value.income)}`} style={{height:`${Math.max(2,Math.abs(value.income)/chartMaximum*100)}%`}}/><span className={value.expense<0?'cash-chart-negative':''} title={`Egresos netos ${cashMoney(value.expense)}`} style={{height:`${Math.max(2,Math.abs(value.expense)/chartMaximum*100)}%`}}/></div><small>{date.slice(8)}/{date.slice(5,7)}</small><span className="adm-sr-only">{civilLabel(date)}: ingresos {cashMoney(value.income)}, egresos {cashMoney(value.expense)}</span></div>)}</div>:<Empty text="El gráfico aparecerá con tus primeros cobros y gastos."/>}<p className="cash-note">Transferencias entre cuentas, saldos iniciales y diferencias de arqueo se muestran por separado y no alteran el flujo neto. Las barras tramadas indican importes netos negativos por devoluciones o reversos.</p></section><section className="adm-panel"><div className="adm-panel-head"><div><h3>¿En qué se fue?</h3><p>Egresos netos por categoría.</p></div></div><div className="cash-category-summary">{categoriesExpense.length?categoriesExpense.map(c=><div key={c.name}><span>{c.name}</span><strong>{cashMoney(c.amount)}</strong><i><b style={{width:`${Math.min(100,Math.max(0,c.amount)/Math.max(1,expense)*100)}%`}}/></i></div>):<Empty text="Todavía no hay egresos en este período."/>}</div></section></div>
      <div className="cash-grid-two"><section className="adm-panel cash-obligation-summary"><div><span>Compromisos pendientes de pago</span><strong>{cashMoney(payables)}</strong><small>{overdue.filter(o=>o.direction==='payable').length} vencidos</small></div><div><span>Cobros pendientes</span><strong>{cashMoney(receivables)}</strong><small>{overdue.filter(o=>o.direction==='receivable').length} vencidos</small></div><button className="adm-text-btn" onClick={()=>setSection('obligations')}>Ver vencimientos <ChevronRight size={16}/></button></section><section className="adm-panel cash-session-summary"><Banknote size={26}/><div><strong>{activeSessions.length} turno{activeSessions.length===1?'':'s'} de efectivo abierto{activeSessions.length===1?'':'s'}</strong><p>{activeSessions.length?'Contá tu efectivo al finalizar el servicio.':'Abrí un turno para cobrar o mover efectivo.'}</p></div><button className="adm-text-btn" onClick={()=>setSection('sessions')}>Ir a turnos</button></section></div>
      <section className="adm-panel"><div className="adm-panel-head"><div><h3>Últimos movimientos del período</h3><p>Cobros y gastos, con sus comprobantes.</p></div><button className="adm-text-btn" onClick={()=>setSection('movements')}>Ver todos <ChevronRight size={16}/></button></div>{movementTable(period.slice(0,6))}</section>
    </>}
    {section==='movements'&&<>
      {pendingRefunds.length>0&&<section className="adm-panel cash-refunds"><div className="adm-panel-head"><div><h3>Devoluciones por pedidos cancelados</h3><p>El cobro permanece en el libro hasta registrar el reintegro.</p></div></div>{pendingRefunds.map(({order,remaining})=><div className="cash-list-row" key={order.id}><div><strong>Pedido #{order.number} · {order.customer.name}</strong><small>Pendiente de devolver: {cashMoney(remaining)}</small></div><button className="adm-btn adm-btn-light" disabled={busy} onClick={()=>open({kind:'refund',order,remaining})}>Registrar devolución</button></div>)}</section>}
      <div className="cash-filters"><label className="cash-search"><Search size={17}/><input aria-label="Buscar movimiento de caja" placeholder="Concepto, proveedor, comprobante, pedido…" value={query} onChange={e=>setQuery(e.target.value)}/></label><label><span className="adm-sr-only">Filtrar cuenta</span><select aria-label="Filtrar cuenta" value={account} onChange={e=>setAccount(e.target.value)}><option value="">Todas las cuentas</option>{cash.accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label><label><span className="adm-sr-only">Filtrar tipo</span><select aria-label="Filtrar tipo de movimiento" value={kind} onChange={e=>setKind(e.target.value)}><option value="">Todos los tipos</option>{Object.entries(cashKindLabels).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><label><span className="adm-sr-only">Filtrar categoría</span><select aria-label="Filtrar categoría" value={category} onChange={e=>setCategory(e.target.value)}><option value="">Todas las categorías</option>{cash.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><button className="adm-btn adm-btn-light" onClick={exportMovements} disabled={!filtered.length}><Download size={16}/>CSV</button></div>
      <section className="adm-panel"><div className="adm-panel-head"><div><h3>Libro de caja <span className="adm-count">{filtered.length}</span></h3><p>Importes por cuenta. Las transferencias tienen una salida y una entrada vinculadas.</p></div>{account&&<strong className="cash-filter-balance">Saldo al corte {cashMoney(cashBalance(cash,account,to||undefined))}</strong>}</div>{movementTable(filtered.slice(currentPage*25,currentPage*25+25))}<div className="cash-pagination"><small>Mostrando {filtered.length?currentPage*25+1:0}–{Math.min((currentPage+1)*25,filtered.length)} de {filtered.length}</small><button className="adm-icon" aria-label="Página anterior" disabled={currentPage===0} onClick={()=>setPage(currentPage-1)}><ChevronLeft size={17}/></button><span>{currentPage+1} / {pages}</span><button className="adm-icon" aria-label="Página siguiente" disabled={currentPage+1>=pages} onClick={()=>setPage(currentPage+1)}><ChevronRight size={17}/></button></div></section>
      <p className="cash-help"><LockKeyhole size={15}/>Los movimientos se conservan. Las correcciones generan un reverso con motivo, sin borrar el registro original.</p>
    </>}
    {section==='sessions'&&<>
      <div className="cash-section-heading"><div><h3>Tu efectivo, contado y explicado.</h3><p>Un turno por caja física. Apertura y cierre dejan constancia del saldo esperado, el conteo y cualquier diferencia.</p></div></div>
      <div className="cash-session-grid">{cash.accounts.filter(a=>a.active&&a.kind==='cash').map(a=>{const session=openSession(cash,a.id);return <article className="adm-panel cash-turn-card" key={a.id}><div className="cash-turn-title"><Banknote size={24}/><div><h3>{a.name}</h3><span className={`cash-pill ${session?'cash-pill-green':''}`}>{session?`Turno #${session.number} abierto`:'Caja cerrada'}</span></div></div><span>Saldo esperado ahora</span><strong className="cash-turn-balance">{cashMoney(cashBalance(cash,a.id))}</strong>{session?<><p>Abierto el {localTime(session.openedAt)}<br/>Fondo contado: {cashMoney(session.openingCents)}</p><button className="adm-btn adm-btn-yellow" disabled={busy} onClick={()=>open({kind:'close',session})}><ClipboardCheck size={16}/>Arquear y cerrar</button></>:<><p>Contá el fondo antes de iniciar el servicio.</p><button className="adm-btn adm-btn-yellow" disabled={busy} onClick={()=>open({kind:'open',account:a})}><Plus size={16}/>Abrir turno</button></>}</article>;})}</div>
      <section className="adm-panel"><div className="adm-panel-head"><div><h3>Historial de turnos</h3><p>Los cierres son definitivos. Las diferencias quedan registradas como ajustes.</p></div><button className="adm-text-btn" disabled={!cash.sessions.length} onClick={()=>csvDownload(`turnos-${today}.csv`,[['Turno','Cuenta','Estado','Apertura','Fondo contado ARS','Saldo antes apertura ARS','Diferencia apertura ARS','Cierre','Esperado ARS','Contado ARS','Diferencia cierre ARS','Observaciones'],...cash.sessions.map(s=>[s.number,s.accountName,s.status==='open'?'Abierto':'Cerrado',localTime(s.openedAt),s.openingCents/100,s.openingExpectedCents/100,s.openingDifferenceCents/100,s.closedAt?localTime(s.closedAt):'',s.expectedCents===undefined?'':s.expectedCents/100,s.countedCents===undefined?'':s.countedCents/100,s.differenceCents===undefined?'':s.differenceCents/100,[s.openingNotes,s.closingNotes||''].filter(Boolean).join(' / ')])])}><Download size={15}/>CSV turnos</button></div>{cash.sessions.length?<div className="cash-turn-history">{[...cash.sessions].sort((a,b)=>b.number-a.number).map(s=><details key={s.id}><summary><span><strong>Turno #{s.number} · {s.accountName}</strong><small>{localTime(s.openedAt)}{s.closedAt?` → ${localTime(s.closedAt)}`:''}</small></span><span className={`cash-pill ${s.status==='open'?'cash-pill-green':''}`}>{s.status==='open'?'Abierto':'Cerrado'}</span><b className={s.differenceCents?'cash-negative':''}>{s.differenceCents===undefined?'En servicio':`Diferencia ${cashMoney(s.differenceCents)}`}</b></summary><div className="cash-turn-detail"><dl><div><dt>Fondo al abrir</dt><dd>{cashMoney(s.openingCents)}</dd></div><div><dt>Diferencia de apertura</dt><dd>{cashMoney(s.openingDifferenceCents)}</dd></div><div><dt>Saldo esperado al cerrar</dt><dd>{s.expectedCents===undefined?'—':cashMoney(s.expectedCents)}</dd></div><div><dt>Efectivo contado al cerrar</dt><dd>{s.countedCents===undefined?'—':cashMoney(s.countedCents)}</dd></div><div><dt>Responsable</dt><dd>{s.closedBy||s.openedBy}</dd></div></dl>{s.openingNotes&&<p>Apertura: {s.openingNotes}</p>}{s.closingNotes&&<p>Cierre: {s.closingNotes}</p>}{s.denominations?.length? <p>Conteo: {s.denominations.map(d=>`${d.count} × ${cashMoney(d.valueCents)}`).join(' · ')}</p>:null}<p>{cash.movements.filter(m=>m.lines.some(l=>l.sessionId===s.id)).length} movimientos vinculados al turno.</p></div></details>)}</div>:<Empty text="El primer turno comienza con el fondo de tu caja."/>}</section>
    </>}
    {section==='obligations'&&<>
      <div className="cash-stats cash-stats-three"><Summary label="Pendiente de pagar" amount={payables} hint="Compras, servicios y otros compromisos"/><Summary label="Pendiente de cobrar" amount={receivables} hint="Importes aún no ingresados al libro"/><article className="cash-stat cash-stat-accent"><span>Compromisos vencidos</span><strong>{overdue.length}</strong><small>Con fecha anterior a hoy y saldo pendiente</small></article></div>
      <div className="cash-section-heading"><div><h3>A pagar y cobrar</h3><p>Programar un compromiso no mueve fondos. Cada pago o cobro parcial crea su movimiento.</p></div><button className="adm-btn adm-btn-yellow" onClick={()=>open({kind:'obligation'})} disabled={busy}><Plus size={16}/>Nuevo compromiso</button></div>
      <div className="adm-filter-chips">{[{id:'pending',label:'Pendientes'},{id:'overdue',label:'Vencidos'},{id:'payable',label:'Por pagar'},{id:'receivable',label:'Por cobrar'},{id:'settled',label:'Saldados'},{id:'cancelled',label:'Cancelados'},{id:'all',label:'Todos'}].map(f=><button key={f.id} className={obligationFilter===f.id?'adm-chip-selected':''} onClick={()=>setObligationFilter(f.id)}>{f.label}</button>)}</div>
      <section className="adm-panel"><div className="cash-obligations">{[...cash.obligations].filter(o=>obligationFilter==='all'||obligationFilter==='overdue'&&o.status==='pending'&&o.dueDate<today||['payable','receivable'].includes(obligationFilter)&&o.direction===obligationFilter&&o.status==='pending'||o.status===obligationFilter).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).map(o=><article key={o.id} className="cash-obligation"><div className={`cash-obligation-icon ${o.direction==='receivable'?'cash-positive':''}`}>{o.direction==='receivable'?<ArrowDownLeft size={21}/>:<ArrowUpRight size={21}/>}</div><div><span className="cash-eyebrow">{o.direction==='payable'?'POR PAGAR':'POR COBRAR'} · {o.categoryName}</span><h4>{o.description}</h4><p>{o.counterparty||'Sin contraparte indicada'} · Vence {civilLabel(o.dueDate)}</p><small>{o.reference&&`Comprobante: ${o.reference} · `}Total {cashMoney(o.totalCents)} · {o.direction==='payable'?'Pagado':'Cobrado'} {cashMoney(o.paidCents)}</small>{o.notes&&<small>{o.notes}</small>}{o.cancellationReason&&<small>Cancelado: {o.cancellationReason}</small>}</div><div className="cash-obligation-amount"><strong>{cashMoney(o.totalCents-o.paidCents)}</strong><span className={`cash-pill ${o.status==='settled'?'cash-pill-green':o.status==='pending'&&o.dueDate<today?'cash-pill-red':''}`}>{o.status==='settled'?'Saldado':o.status==='cancelled'?'Cancelado':o.dueDate<today?'Vencido':'Pendiente'}</span></div>{o.status==='pending'&&<div className="cash-obligation-actions"><button className="adm-btn adm-btn-light" disabled={busy} onClick={()=>open({kind:'settle',obligation:o})}>{o.direction==='payable'?'Registrar pago':'Registrar cobro'}</button><button className="adm-text-btn cash-negative" disabled={busy} onClick={()=>open({kind:'cancel',obligation:o})}>Cancelar saldo</button></div>}</article>)}{!cash.obligations.filter(o=>obligationFilter==='all'||obligationFilter==='overdue'&&o.status==='pending'&&o.dueDate<today||['payable','receivable'].includes(obligationFilter)&&o.direction===obligationFilter&&o.status==='pending'||o.status===obligationFilter).length&&<Empty text="No hay compromisos en esta vista."/>}</div></section>
    </>}
    {section==='reconciliation'&&<>
      <div className="cash-section-heading"><div><h3>El libro y tu extracto, cara a cara.</h3><p>Compará bancos y billeteras al cierre de una fecha. Las diferencias se explican y quedan en el historial.</p></div><button className="adm-btn adm-btn-yellow" disabled={busy||!cash.accounts.some(a=>a.active&&a.kind!=='cash')} onClick={()=>open({kind:'reconcile'})}><ClipboardCheck size={16}/>Conciliar cuenta</button></div>
      <div className="cash-alert cash-alert-info"><LockKeyhole size={20}/><div><strong>Una conciliación fija un corte.</strong><p>Después no se podrán agregar movimientos con fecha igual o anterior a ese corte. La comparación no modifica el saldo ni registra gastos automáticamente.</p></div></div>
      <div className="cash-reconcile-accounts">{cash.accounts.filter(a=>a.kind!=='cash').map(a=>{const last=[...cash.reconciliations].filter(r=>r.accountId===a.id).sort((x,y)=>y.throughDate.localeCompare(x.throughDate))[0];return <article className="adm-panel" key={a.id}><div><AccountIcon kind={a.kind}/><strong>{a.name}</strong></div><b>{cashMoney(cashBalance(cash,a.id))}</b><small>{last?`Último corte ${civilLabel(last.throughDate)} · diferencia ${cashMoney(last.differenceCents)}`:'Todavía sin conciliaciones'}</small></article>;})}</div>
      <section className="adm-panel"><div className="adm-panel-head"><div><h3>Historial de conciliaciones</h3><p>Saldo del libro, saldo del extracto y diferencia registrada.</p></div></div>{cash.reconciliations.length?<div className="cash-turn-history">{[...cash.reconciliations].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(r=><details key={r.id}><summary><span><strong>{r.accountName}</strong><small>Corte {civilLabel(r.throughDate)} · registrado {localTime(r.createdAt)}</small></span><span className={`cash-pill ${r.differenceCents?'cash-pill-red':'cash-pill-green'}`}>{r.differenceCents?'Con diferencia':'Coincide'}</span><b>{cashMoney(r.differenceCents)}</b></summary><div className="cash-turn-detail"><dl><div><dt>Saldo del libro al corte</dt><dd>{cashMoney(r.bookCents)}</dd></div><div><dt>Saldo del extracto</dt><dd>{cashMoney(r.statementCents)}</dd></div><div><dt>Movimientos incluidos</dt><dd>{r.movementIds.length}</dd></div><div><dt>Responsable</dt><dd>{r.actor}</dd></div></dl>{r.notes&&<p>{r.notes}</p>}</div></details>)}</div>:<Empty text="Tus conciliaciones aparecerán acá."/>}</section>
    </>}
    {section==='settings'&&<>
      <section className="adm-panel cash-settings-panel"><div className="adm-panel-head"><div><h3>Cuentas del comercio</h3><p>Separá el dinero según dónde está. Los nombres anteriores se conservan en cada movimiento.</p></div><button className="adm-btn adm-btn-light" disabled={busy} onClick={()=>open({kind:'account'})}><Plus size={16}/>Nueva cuenta</button></div>{cash.accounts.map(a=><div className="cash-list-row" key={a.id}><AccountIcon kind={a.kind}/><div><strong>{a.name}</strong><small>{cashAccountKinds[a.kind]} · {a.active?'Activa':'Archivada'} · {cashMoney(cashBalance(cash,a.id))}</small></div><button className="adm-icon" disabled={busy} aria-label={`Editar cuenta ${a.name}`} onClick={()=>open({kind:'account',account:a})}><Pencil size={16}/></button></div>)}<p className="cash-note">Una cuenta sólo se archiva sin fondos y sin turno abierto. El saldo inicial es una apertura de fondos, no un ingreso del período.</p></section>
      <section className="adm-panel"><div className="adm-panel-head"><div><h3>Categorías de ingresos y egresos</h3><p>Ordená los conceptos para que los reportes expliquen tu negocio.</p></div><button className="adm-btn adm-btn-light" disabled={busy} onClick={()=>open({kind:'category'})}><Plus size={16}/>Nueva categoría</button></div><div className="cash-category-grid">{cash.categories.map(c=><div key={c.id}><span className={`cash-category-dot ${c.direction==='income'?'cash-category-income':''}`}/><span><strong>{c.name}</strong><small>{c.direction==='income'?'Ingreso':'Egreso'} · {c.active?'Activa':'Archivada'}</small></span><button className="adm-icon" disabled={busy} aria-label={`Editar categoría ${c.name}`} onClick={()=>open({kind:'category',category:c})}><Pencil size={15}/></button></div>)}</div></section>
    </>}
    {section==='audit'&&<section className="adm-panel"><div className="adm-panel-head"><div><h3>La historia completa</h3><p>Aperturas, cierres, configuraciones y operaciones quedan asociados a su responsable.</p></div><button className="adm-text-btn" disabled={!cash.audit.length} onClick={()=>csvDownload(`auditoria-caja-${today}.csv`,[['Fecha Argentina','Responsable','Acción','Detalle','Referencia'],...cash.audit.map(a=>[localTime(a.createdAt),a.actor,a.action,a.detail,a.entityId])])}><Download size={15}/>CSV auditoría</button></div>{cash.audit.length?<ol className="cash-audit">{[...cash.audit].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(page*50,page*50+50).map(a=><li key={a.id}><span><History size={15}/></span><div><strong>{a.action}</strong><p>{a.detail}</p><small>{localTime(a.createdAt)} · {a.actor}</small></div></li>)}</ol>:<Empty text="Cada operación de caja dejará su registro acá."/>}<div className="cash-pagination"><small>{cash.audit.length} registros</small><button className="adm-icon" aria-label="Auditoría anterior" disabled={page===0} onClick={()=>setPage(page-1)}><ChevronLeft size={17}/></button><span>Página {page+1}</span><button className="adm-icon" aria-label="Auditoría siguiente" disabled={(page+1)*50>=cash.audit.length} onClick={()=>setPage(page+1)}><ChevronRight size={17}/></button></div></section>}
    {dialog?.kind==='detail'&&<MovementDetail cash={cash} movement={dialog.movement} onClose={()=>setDialog(null)} onReverse={()=>open({kind:'reverse',movement:dialog.movement})} onRefund={()=>{const order=state.orders.find(o=>o.id===dialog.movement.orderId);if(order){const remaining=cash.movements.filter(m=>m.orderId===order.id).reduce((s,m)=>s+sumLines(m),0);open({kind:'refund',order,remaining});}}}/>} 
    {dialog&&dialog.kind!=='detail'&&<CashDialog key={dialog.key} dialog={dialog} cash={cash} busy={busy} onClose={()=>setDialog(null)} onAction={onAction} serverError={serverError}/>}
  </section>;
}

function MovementDetail({cash,movement:m,onClose,onReverse,onRefund}:{cash:CashState;movement:CashMovement;onClose:()=>void;onReverse:()=>void;onRefund:()=>void}) {
  const reversed=cash.movements.find(item=>item.reversalOf===m.id);
  const original=m.reversalOf?cash.movements.find(item=>item.id===m.reversalOf):undefined;
  const refundable=m.kind==='sale'&&cash.movements.filter(item=>item.orderId===m.orderId).reduce((sum,item)=>sum+sumLines(item),0)>0;
  return <Modal title={`Movimiento #${m.number}`} subtitle={`${cashKindLabels[m.kind]} · ${localTime(m.occurredAt)}`} onClose={onClose}><div className="cash-detail"><h3>{m.description}</h3><div className="cash-detail-lines">{m.lines.map((l,i)=><div key={`${l.accountId}-${i}`}><span>{l.accountName}{l.sessionId&&<small>Turno #{cash.sessions.find(s=>s.id===l.sessionId)?.number||'—'}</small>}</span><strong className={l.amountCents>0?'cash-positive':'cash-negative'}>{l.amountCents>0?'+':''}{cashMoney(l.amountCents)}</strong></div>)}</div><dl><div><dt>Categoría</dt><dd>{m.categoryName||'Movimiento interno'}</dd></div><div><dt>Contraparte</dt><dd>{m.counterparty||'Sin indicar'}</dd></div><div><dt>Comprobante / referencia</dt><dd>{m.reference||'Sin indicar'}</dd></div><div><dt>Registrado por</dt><dd>{m.actor} · {localTime(m.createdAt)}</dd></div>{m.orderNumber&&<div><dt>Pedido vinculado</dt><dd>#{m.orderNumber}</dd></div>}{original&&<div><dt>Revierte al movimiento</dt><dd>#{original.number}</dd></div>}{reversed&&<div><dt>Revertido por</dt><dd>Movimiento #{reversed.number} · {localTime(reversed.createdAt)}</dd></div>}<div><dt>Conciliación</dt><dd>{cash.reconciliations.filter(r=>r.movementIds.includes(m.id)).map(r=>`${r.accountName}, corte ${civilLabel(r.throughDate)}`).join(' · ')||'Sin conciliación vinculada'}</dd></div></dl>{m.notes&&<p>{m.notes}</p>}{m.historical&&<p className="cash-help">Importado al activar caja. La fecha histórica proviene del pedido porque el registro anterior no conservaba la hora del cobro.</p>}<div className="adm-form-footer">{['income','expense','transfer','refund'].includes(m.kind)&&!reversed&&<button className="adm-btn adm-btn-danger" onClick={onReverse}>Registrar reverso</button>}{refundable&&<button className="adm-btn adm-btn-light" onClick={onRefund}>Registrar devolución</button>}<button className="adm-btn adm-btn-yellow" onClick={onClose}>Listo</button></div></div></Modal>;
}

function CashDialog({dialog,cash,busy,onClose,onAction,serverError}:{dialog:Exclude<Dialog,{kind:'detail'}>;cash:CashState;busy:boolean;onClose:()=>void;onAction:PanelProps['onAction'];serverError?:string}) {
  const [requestId]=useState(uid);
  const [openedAt]=useState(()=>new Date().toISOString());
  const usable=cash.accounts.filter(a=>canUse(cash,a));
  const [values,setValues]=useState<Record<string,string>>(()=>{
    const common={accountId:usable[0]?.id||'',amount:'',description:'',counterparty:'',reference:'',notes:'',reason:'',date:cashDate(new Date()),direction:'payable',categoryId:'',name:'',kind:'bank',active:'yes',opening:'0',countMode:'total',toAccountId:usable[1]?.id||''};
    if(dialog.kind==='entry')common.categoryId=(dialog.direction==='income'?cash.categories.find(c=>c.id==='otros-ingresos'&&c.active):undefined)?.id||cash.categories.find(c=>c.active&&c.direction===dialog.direction&&c.id!=='ventas')?.id||'';
    if(dialog.kind==='open')return {...common,accountId:dialog.account.id,amount:moneyInput(cashBalance(cash,dialog.account.id))};
    if(dialog.kind==='close')return {...common,accountId:dialog.session.accountId};
    if(dialog.kind==='account')return {...common,name:dialog.account?.name||'',kind:dialog.account?.kind||'bank',active:dialog.account?.active===false?'no':'yes'};
    if(dialog.kind==='category')return {...common,name:dialog.category?.name||'',direction:dialog.category?.direction||'expense',active:dialog.category?.active===false?'no':'yes'};
    if(dialog.kind==='obligation')common.categoryId=cash.categories.find(c=>c.active&&c.direction==='expense')?.id||'';
    if(dialog.kind==='settle')return {...common,amount:moneyInput(dialog.obligation.totalCents-dialog.obligation.paidCents),reference:dialog.obligation.reference};
    if(dialog.kind==='refund')return {...common,amount:moneyInput(dialog.remaining)};
    if(dialog.kind==='reconcile')return {...common,accountId:cash.accounts.find(a=>a.active&&a.kind!=='cash')?.id||'',date:cashDate(new Date(Date.now()-86400000))};
    return common;
  });
  const [counts,setCounts]=useState<Record<number,string>>({});
  const [error,setError]=useState('');
  const [initialBalances]=useState(()=>Object.fromEntries(cash.accounts.map(a=>[a.id,cashBalance(cash,a.id)])));
  const [accountId]=useState(()=>dialog.kind==='account'?dialog.account?.id||`cuenta-${uid()}`:dialog.kind==='category'?dialog.category?.id||`categoria-${uid()}`:'');
  const value=(key:string)=>values[key]||'';
  const set=(key:string,next:string)=>{setValues(previous=>({...previous,[key]:next}));setError('');};
  const selected=cash.accounts.find(a=>a.id===value('accountId'));
  const currentBalance=selected?cashBalance(cash,selected.id):0;
  const counted=values.countMode==='denominations'?denominations.reduce((sum,d)=>sum+d*(Number(counts[d])||0),0):(()=>{try{return parseCents(value('amount'),true);}catch{return 0;}})();
  const expected=initialBalances[value('accountId')]||0;
  const bookAtCut=selected?cashBalance(cash,selected.id,value('date')||undefined):0;
  const [reconcileExpected,setReconcileExpected]=useState(bookAtCut);
  useEffect(()=>{if(dialog.kind==='reconcile')setReconcileExpected(cashBalance(cash,value('accountId'),value('date')||undefined));},[values.accountId,values.date]); // Snapshot changes only when the operator changes the chosen cut.
  const names:Record<Exclude<Dialog['kind'],'detail'>,string>={entry:dialog.kind==='entry'&&dialog.direction==='income'?'Registrar ingreso':'Registrar egreso',transfer:'Transferir entre cuentas',open:'Abrir turno de efectivo',close:'Arqueo y cierre de caja',account:dialog.kind==='account'&&dialog.account?'Editar cuenta':'Nueva cuenta',category:dialog.kind==='category'&&dialog.category?'Editar categoría':'Nueva categoría',obligation:'Nuevo compromiso',settle:dialog.kind==='settle'&&dialog.obligation.direction==='receivable'?'Registrar cobro':'Registrar pago',cancel:'Cancelar saldo pendiente',reverse:'Revertir movimiento',refund:'Registrar devolución',reconcile:'Conciliar con el extracto'};
  const field=(key:string,label:string,options:{required?:boolean;placeholder?:string;minLength?:number;maxLength?:number;multiline?:boolean;type?:string;min?:string;max?:string}={})=><label>{label}{options.multiline?<textarea required={options.required} minLength={options.minLength||(options.required?3:undefined)} maxLength={options.maxLength||500} value={value(key)} onChange={e=>set(key,e.target.value)} placeholder={options.placeholder}/>:<input required={options.required} type={options.type||'text'} min={options.min} max={options.max} minLength={options.minLength||(options.required&&['name','description','reason'].includes(key)?(key==='name'?2:3):undefined)} maxLength={options.maxLength||200} value={value(key)} onChange={e=>set(key,e.target.value)} placeholder={options.placeholder} inputMode={['amount','opening','statement'].includes(key)?'decimal':undefined}/>}</label>;
  const accountField=(label='Cuenta')=><label>{label}<select required value={value('accountId')} onChange={e=>set('accountId',e.target.value)}><option value="">Elegí una cuenta</option><AccountOptions cash={cash}/></select>{!usable.length&&<small>Abrí un turno de efectivo o creá una cuenta bancaria para registrar movimientos.</small>}</label>;
  const categoryField=(direction:'income'|'expense')=><label>Categoría<select required value={value('categoryId')} onChange={e=>set('categoryId',e.target.value)}><option value="">Elegí una categoría</option>{cash.categories.filter(c=>c.active&&c.direction===direction&&c.id!=='ventas').map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>;
  async function submit(e:FormEvent) {
    e.preventDefault();if(busy)return;setError('');
    try {
      const base={requestId}; let action:CashAction;
      switch(dialog.kind){
        case 'entry':action={...base,type:'cash-entry',direction:dialog.direction,entry:{accountId:value('accountId'),amountCents:parseCents(value('amount')),description:value('description'),categoryId:value('categoryId'),counterparty:value('counterparty'),reference:value('reference'),notes:value('notes'),occurredAt:value('date')===cashDate(openedAt)?openedAt:`${value('date')}T15:00:00.000Z`}};break;
        case 'transfer':action={...base,type:'cash-transfer',fromAccountId:value('accountId'),toAccountId:value('toAccountId'),amountCents:parseCents(value('amount')),description:value('description'),reference:value('reference'),notes:value('notes')};break;
        case 'open':action={...base,type:'cash-open',accountId:dialog.account.id,openingCents:parseCents(value('amount'),true),expectedBalanceCents:expected,notes:value('notes')};break;
        case 'close': {
          const denominationCounts=values.countMode==='denominations'?denominations.map(d=>({valueCents:d,count:Number(counts[d])||0})).filter(d=>d.count>0):[];
          if(denominationCounts.some(d=>!Number.isSafeInteger(d.count)||d.count<0))throw new Error('Las cantidades de billetes y monedas deben ser números enteros.');
          action={...base,type:'cash-close',sessionId:dialog.session.id,countedCents:values.countMode==='denominations'?counted:parseCents(value('amount'),true),expectedBalanceCents:expected,notes:value('notes'),denominations:denominationCounts};break;
        }
        case 'account':action={...base,type:'cash-account',account:{id:accountId,name:value('name'),kind:value('kind') as CashAccount['kind'],active:value('active')==='yes'},openingCents:dialog.account?0:parseCents(value('opening'),true)};break;
        case 'category':action={...base,type:'cash-category',category:{id:accountId,name:value('name'),direction:value('direction') as CashCategory['direction'],active:value('active')==='yes'}};break;
        case 'obligation':action={...base,type:'cash-obligation',obligation:{direction:value('direction') as CashObligation['direction'],description:value('description'),counterparty:value('counterparty'),reference:value('reference'),notes:value('notes'),categoryId:value('categoryId'),totalCents:parseCents(value('amount')),dueDate:value('date')}};break;
        case 'settle':action={...base,type:'cash-settle',obligationId:dialog.obligation.id,accountId:value('accountId'),amountCents:parseCents(value('amount')),reference:value('reference'),notes:value('notes')};break;
        case 'cancel':action={...base,type:'cash-cancel-obligation',obligationId:dialog.obligation.id,reason:value('reason')};break;
        case 'reverse':action={...base,type:'cash-reverse',movementId:dialog.movement.id,reason:value('reason')};break;
        case 'refund':action={...base,type:'cash-refund',orderId:dialog.order.id,accountId:value('accountId'),amountCents:parseCents(value('amount')),reason:value('reason'),reference:value('reference')};break;
        case 'reconcile':action={...base,type:'cash-reconcile',accountId:value('accountId'),throughDate:value('date'),statementCents:parseCents(value('statement'),true),expectedBookCents:reconcileExpected,notes:value('notes')};break;
      }
      if(await onAction(action,'La operación de caja quedó registrada.'))onClose();
      else setError('La operación no se pudo guardar. Revisá el aviso del panel. Si los saldos cambiaron, cerrá esta ventana y abrila nuevamente.');
    }catch(e){setError(e instanceof Error?e.message:'Revisá los datos antes de continuar.');}
  }
  return <Modal title={names[dialog.kind]} subtitle={dialog.kind==='close'?`${dialog.session.accountName} · Turno #${dialog.session.number}`:dialog.kind==='open'?dialog.account.name:undefined} busy={busy} onClose={onClose} wide={dialog.kind==='close'}><form className="adm-form cash-form" onSubmit={submit}>
    {dialog.kind==='entry'&&<><div className="adm-form-grid">{accountField()}{field('amount','Importe ($)',{required:true,placeholder:'0,00'})}</div>{categoryField(dialog.direction)}{field('description','Concepto',{required:true,maxLength:200,placeholder:dialog.direction==='expense'?'Ej. Compra de carne para el servicio':'Ej. Aporte para el local'})}<div className="adm-form-grid">{field('counterparty',dialog.direction==='expense'?'Proveedor / destinatario':'Cliente / origen de fondos',{maxLength:120})}{field('reference','Comprobante o referencia',{maxLength:120})}</div>{field('date','Fecha del movimiento (Argentina)',{type:'date',required:true,max:cashDate(new Date())})}{field('notes','Observaciones',{multiline:true})}<p className="cash-help">El movimiento impacta en la cuenta elegida. Registrar un egreso por insumos no modifica el inventario: la mercadería se carga desde Inventario.</p></>}
    {dialog.kind==='transfer'&&<><div className="adm-form-grid">{accountField('Sale de')}<label>Ingresa en<select required value={value('toAccountId')} onChange={e=>set('toAccountId',e.target.value)}><option value="">Elegí la cuenta de destino</option><AccountOptions cash={cash} exclude={value('accountId')}/></select></label></div>{field('amount','Importe a transferir ($)',{required:true,placeholder:'0,00'})}{field('description','Motivo',{required:true,placeholder:'Ej. Depósito de efectivo en el banco'})}{field('reference','Referencia de la transferencia',{maxLength:120})}{field('notes','Observaciones',{multiline:true})}<p className="cash-help">El total del comercio no cambia. Ambas cuentas conservan su movimiento vinculado.</p></>}
    {(dialog.kind==='open'||dialog.kind==='close')&&<><div className="cash-count-preview"><span>Saldo esperado al abrir esta ventana</span><strong>{cashMoney(expected)}</strong></div>{currentBalance!==expected&&<ErrorMessage message="El saldo cambió mientras contabas. Cerrá esta ventana, actualizá la caja y volvé a contar antes de confirmar."/>}{dialog.kind==='open'?field('amount','Fondo de efectivo contado ($)',{required:true,placeholder:'0,00'}):<><div className="adm-segmented"><button type="button" className={value('countMode')==='total'?'adm-selected':''} onClick={()=>set('countMode','total')}>Ingresar total</button><button type="button" className={value('countMode')==='denominations'?'adm-selected':''} onClick={()=>set('countMode','denominations')}>Contar billetes y monedas</button></div>{value('countMode')==='total'?field('amount','Efectivo real contado ($)',{required:true,placeholder:'0,00'}):<div className="cash-denominations">{denominations.map(d=><label key={d}><span>{cashMoney(d)}</span><input aria-label={`Cantidad de ${cashMoney(d)}`} type="number" min="0" max="1000000" step="1" inputMode="numeric" value={counts[d]||''} onChange={e=>setCounts(prev=>({...prev,[d]:e.target.value}))} placeholder="0"/><small>{cashMoney(d*(Number(counts[d])||0))}</small></label>)}</div>}</>}<div className="cash-count-totals"><span>Contado <b>{cashMoney(counted)}</b></span><span>Diferencia <b className={counted-expected?'cash-negative':'cash-positive'}>{cashMoney(counted-expected)}</b></span></div>{field('notes',counted!==expected?'Motivo de la diferencia (obligatorio)':'Observaciones del turno',{required:counted!==expected,multiline:true})}<p className="cash-help">{dialog.kind==='close'?'El cierre conservará este conteo y no se podrá editar. Si hay diferencia, se registrará un ajuste para que el saldo refleje el efectivo contado.':'Si el fondo contado no coincide con el saldo del libro, la diferencia quedará registrada como ajuste de apertura.'}</p></>}
    {dialog.kind==='account'&&<>{field('name','Nombre de la cuenta',{required:true,maxLength:80,placeholder:'Ej. Caja mostrador'})}<label>Tipo de cuenta<select disabled={!!dialog.account} value={value('kind')} onChange={e=>set('kind',e.target.value)}>{Object.entries(cashAccountKinds).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>{!dialog.account&&field('opening','Saldo inicial ($)',{required:true})}{dialog.account&&<label>Estado<select value={value('active')} onChange={e=>set('active',e.target.value)}><option value="yes">Activa</option><option value="no">Archivada</option></select></label>}<p className="cash-help">El saldo inicial representa fondos existentes y no se incluye entre los ingresos del período. Los saldos de cuentas existentes se modifican con movimientos trazables.</p></>}
    {dialog.kind==='category'&&<>{field('name','Nombre de la categoría',{required:true,maxLength:80,placeholder:'Ej. Servicios del local'})}<label>Se utiliza para<select disabled={!!dialog.category} value={value('direction')} onChange={e=>set('direction',e.target.value)}><option value="expense">Egresos</option><option value="income">Ingresos</option></select></label><label>Estado<select value={value('active')} onChange={e=>set('active',e.target.value)}><option value="yes">Activa</option><option value="no">Archivada</option></select></label><p className="cash-help">Archivar una categoría la retira de nuevas cargas. Los movimientos históricos conservan su categoría original.</p></>}
    {dialog.kind==='obligation'&&<><label>Tipo de compromiso<select value={value('direction')} onChange={e=>{set('direction',e.target.value);set('categoryId',cash.categories.find(c=>c.active&&c.direction===(e.target.value==='payable'?'expense':'income')&&c.id!=='ventas')?.id||'');}}><option value="payable">Tengo que pagar</option><option value="receivable">Tengo que cobrar</option></select></label>{field('description','Concepto',{required:true,placeholder:'Ej. Factura del proveedor de bebidas'})}<div className="adm-form-grid">{field('amount','Importe total ($)',{required:true,placeholder:'0,00'})}{field('date','Fecha de vencimiento',{required:true,type:'date'})}</div>{categoryField(value('direction')==='payable'?'expense':'income')}{field('counterparty','Proveedor / cliente',{maxLength:120})}{field('reference','Comprobante / referencia',{maxLength:120})}{field('notes','Observaciones',{multiline:true})}<p className="cash-help">Este compromiso no modifica la caja hasta que registres un pago o cobro, que puede ser parcial.</p></>}
    {dialog.kind==='settle'&&<><div className="cash-count-preview"><span>{dialog.obligation.description}<small>Saldo pendiente</small></span><strong>{cashMoney(dialog.obligation.totalCents-dialog.obligation.paidCents)}</strong></div>{accountField()} {field('amount',dialog.obligation.direction==='payable'?'Importe pagado ($)':'Importe cobrado ($)',{required:true})}{field('reference','Comprobante del pago / cobro',{maxLength:120})}{field('notes','Observaciones',{multiline:true})}<p className="cash-help">Podés registrar un importe parcial. El saldo restante seguirá pendiente.</p></>}
    {dialog.kind==='cancel'&&<><p className="cash-help">Se cancelará el saldo de <strong>{dialog.obligation.description}</strong> por {cashMoney(dialog.obligation.totalCents-dialog.obligation.paidCents)}. Los pagos o cobros ya realizados se conservan.</p>{field('reason','Motivo de cancelación',{required:true,multiline:true})}</>}
    {dialog.kind==='reverse'&&<><p className="cash-help">Se generará el movimiento contrario al <strong>#{dialog.movement.number}: {dialog.movement.description}</strong>. El original permanecerá visible. Las cuentas deben estar disponibles y tener fondos suficientes.</p>{field('reason','Motivo del reverso',{required:true,multiline:true})}</>}
    {dialog.kind==='refund'&&<><div className="cash-count-preview"><span>Pedido #{dialog.order.number}<small>{dialog.order.customer.name} · Máximo a devolver</small></span><strong>{cashMoney(dialog.remaining)}</strong></div>{accountField('La devolución sale de')}{field('amount','Importe efectivamente devuelto ($)',{required:true})}{field('reason','Motivo de la devolución',{required:true,multiline:true})}{field('reference','Comprobante de devolución',{maxLength:120})}<p className="cash-help">Confirmá sólo cuando el dinero haya sido reintegrado. Esto no modifica el stock ni el estado del pedido.</p></>}
    {dialog.kind==='reconcile'&&<><label>Cuenta a conciliar<select required value={value('accountId')} onChange={e=>set('accountId',e.target.value)}><option value="">Elegí una cuenta</option>{cash.accounts.filter(a=>a.active&&a.kind!=='cash').map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></label>{field('date','Fecha de corte del extracto (Argentina)',{required:true,type:'date',max:cashDate(new Date(Date.now()-86400000))})}<div className="cash-count-preview"><span>Saldo del libro al corte</span><strong>{cashMoney(reconcileExpected)}</strong></div>{bookAtCut!==reconcileExpected&&<ErrorMessage message="El libro cambió desde que elegiste el corte. Cerrá esta ventana y volvé a comparar."/>}{field('statement','Saldo del extracto al corte ($)',{required:true,placeholder:'0,00'})}<div className="cash-count-preview"><span>Diferencia (extracto menos libro)</span><strong>{(()=>{try{return cashMoney(parseCents(value('statement'),true)-reconcileExpected);}catch{return '—';}})()}</strong></div>{field('notes','Detalle de la comparación y motivo si hay diferencias',{multiline:true,required:(()=>{try{return parseCents(value('statement'),true)!==reconcileExpected;}catch{return false;}})()})}<p className="cash-help">Revisá comisiones, retenciones y acreditaciones. Si falta un movimiento, cargalo antes de conciliar. Luego del corte no podrás registrar movimientos con esa fecha o anteriores.</p></>}
    <ErrorMessage message={error?(serverError||error):''}/><div className="adm-form-footer"><button type="button" className="adm-btn adm-btn-light" onClick={onClose} disabled={busy}>Cancelar</button><button className="adm-btn adm-btn-yellow" disabled={busy||(['open','close'].includes(dialog.kind)&&currentBalance!==expected)||(dialog.kind==='reconcile'&&bookAtCut!==reconcileExpected)}><Check size={16}/>{busy?'Guardando…':dialog.kind==='close'?'Confirmar cierre':dialog.kind==='reverse'?'Confirmar reverso':'Guardar registro'}</button></div>
  </form></Modal>;
}

export function PaymentDialog({order,cash,busy,onClose,onSave,error:serverError}:{order:Order;cash:CashState;busy:boolean;onClose:()=>void;onSave:(payments:CashPayment[])=>Promise<boolean>;error?:string}) {
  const accounts=cash.accounts.filter(a=>canUse(cash,a));
  const preferred=accounts.find(a=>a.kind===(order.paymentMethod==='efectivo'?'cash':order.paymentMethod==='transferencia'?'bank':'wallet'));
  const [payments,setPayments]=useState([{id:uid(),accountId:preferred?.id||'',amount:moneyInput(Math.round(order.total*100))}]);
  const [error,setError]=useState('');
  const totalCents=Math.round(order.total*100);
  const collected=payments.reduce((sum,p)=>{try{return sum+parseCents(p.amount,true);}catch{return sum;}},0);
  if(totalCents===0)return <Modal title={`Confirmar pedido bonificado · #${order.number}`} subtitle={order.customer.name} busy={busy} onClose={onClose}><form className="adm-form cash-form" onSubmit={async e=>{e.preventDefault();if(busy)return;setError('');try{if(await onSave([]))onClose();else setError('No se pudo confirmar el pedido bonificado. Revisá el aviso del panel.');}catch(e){setError(e instanceof Error?e.message:'No se pudo confirmar el pedido.');}}}>
    <div className="cash-payment-total"><span>Total bonificado</span><strong>{cashMoney(0)}</strong></div><p className="cash-help">Este pedido no requiere un cobro ni una cuenta de ingreso. Al confirmar se registrará la venta bonificada y se descontarán los ingredientes una sola vez, sin mover dinero. No necesitás abrir un turno de efectivo.</p><ErrorMessage message={error?(serverError||error):''}/><div className="adm-form-footer"><button type="button" className="adm-btn adm-btn-light" disabled={busy} onClick={onClose}>Cancelar</button><button className="adm-btn adm-btn-yellow" disabled={busy}><Check size={16}/>{busy?'Confirmando…':'Confirmar pedido bonificado'}</button></div>
  </form></Modal>;
  return <Modal title={`Verificar cobro · pedido #${order.number}`} subtitle={`${order.customer.name} · Elegí dónde ingresó el dinero.`} busy={busy} onClose={onClose}><form className="adm-form cash-form" onSubmit={async e=>{e.preventDefault();if(busy)return;setError('');try{const values=payments.map(p=>({accountId:p.accountId,amountCents:parseCents(p.amount)}));if(values.reduce((sum,p)=>sum+p.amountCents,0)!==totalCents)throw new Error('La suma de los importes debe coincidir exactamente con el total del pedido.');if(new Set(values.map(p=>p.accountId)).size!==values.length)throw new Error('Cada cuenta puede aparecer una sola vez. Sumá los importes de la misma cuenta.');if(await onSave(values))onClose();else setError('No se pudo verificar el cobro. Revisá el aviso del panel y el turno de efectivo.');}catch(e){setError(e instanceof Error?e.message:'Revisá los importes.');}}}>
    <div className="cash-payment-total"><span>Total del pedido<small>Medio solicitado: {order.paymentMethod==='efectivo'?'Efectivo':order.paymentMethod==='transferencia'?'Transferencia':'Mercado Pago'}</small></span><strong>{cashMoney(totalCents)}</strong></div>
    {!accounts.length&&<ErrorMessage message="Abrí un turno de efectivo desde Caja → Turnos y arqueos para poder verificar este cobro, o activá una cuenta bancaria."/>}
    {cash.accounts.some(a=>a.active&&a.kind==='cash'&&!openSession(cash,a.id))&&<p className="cash-help">Para ingresar efectivo necesitás un turno abierto en esa caja. Los cobros por banco o billetera no requieren turno.</p>}
    {payments.map((p,index)=><div className="cash-payment-row" key={p.id}><label>Cuenta {payments.length>1?index+1:''}<select required value={p.accountId} onChange={e=>setPayments(rows=>rows.map(row=>row.id===p.id?{...row,accountId:e.target.value}:row))}><option value="">Elegí una cuenta</option><AccountOptions cash={cash}/></select></label><label>Importe recibido ($)<input required inputMode="decimal" value={p.amount} onChange={e=>setPayments(rows=>rows.map(row=>row.id===p.id?{...row,amount:e.target.value}:row))}/></label>{payments.length>1&&<button type="button" className="adm-icon" aria-label={`Quitar forma de cobro ${index+1}`} onClick={()=>setPayments(rows=>rows.filter(row=>row.id!==p.id))}><X size={17}/></button>}</div>)}
    {payments.length<Math.min(10,accounts.length)&&<button type="button" className="adm-text-btn" onClick={()=>{const account=accounts.find(a=>!payments.some(p=>p.accountId===a.id));setPayments(rows=>[...rows,{id:uid(),accountId:account?.id||'',amount:moneyInput(Math.max(0,totalCents-collected))}]);}}><Plus size={16}/>Dividir entre otra cuenta</button>}
    <div className="cash-count-totals"><span>Asignado <b>{cashMoney(collected)}</b></span><span>Falta asignar <b className={totalCents-collected?'cash-negative':'cash-positive'}>{cashMoney(totalCents-collected)}</b></span></div><p className="cash-help">Verificar registra el ingreso en caja y descuenta los ingredientes una sola vez. Cargá el importe exacto aplicado al pedido; el vuelto no es un ingreso.</p><ErrorMessage message={error?(serverError||error):''}/><div className="adm-form-footer"><button type="button" className="adm-btn adm-btn-light" disabled={busy} onClick={onClose}>Cancelar</button><button className="adm-btn adm-btn-yellow" disabled={busy||!accounts.length||collected!==totalCents}><Check size={16}/>{busy?'Verificando…':'Confirmar cobro'}</button></div>
  </form></Modal>;
}
